def move_existing_resumes_to_private_storage(apps, schema_editor):
    Resume = apps.get_model('portal', 'Resume')
    for resume in Resume.objects.exclude(resume_file=''):
        relative_name = str(resume.resume_file.name)
        old_path = Path(settings.MEDIA_ROOT) / relative_name
        new_path = Path(settings.PRIVATE_MEDIA_ROOT) / relative_name
        if old_path.exists() and not new_path.exists():
            new_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.move(str(old_path), str(new_path))

    public_resume_root = Path(settings.MEDIA_ROOT) / 'resumes'
    legacy_resume_root = Path(settings.PRIVATE_MEDIA_ROOT) / 'legacy_resumes'
    if public_resume_root.exists():
        for old_path in public_resume_root.rglob('*'):
            if not old_path.is_file():
                continue
            relative_path = old_path.relative_to(public_resume_root)
            new_path = legacy_resume_root / relative_path
            new_path.parent.mkdir(parents=True, exist_ok=True)
            counter = 1
            while new_path.exists():
                new_path = new_path.with_name(f'{new_path.stem}_{counter}{new_path.suffix}')
                counter += 1
            shutil.move(str(old_path), str(new_path))


def snapshot_existing_application_matches(apps, schema_editor):
    Application = apps.get_model('portal', 'Application')
    Recommendation = apps.get_model('portal', 'Recommendation')
    for application in Application.objects.all().iterator():
        recommendation = Recommendation.objects.filter(
            user_id=application.user_id,
            job_id=application.job_id,
        ).first()
        if recommendation:
            application.match_score = recommendation.score
            application.matched_skills = recommendation.matched_skills
            application.missing_skills = recommendation.missing_skills
            application.save(update_fields=['match_score', 'matched_skills', 'missing_skills'])


